package com.resumeanalyzer.config;
import com.resumeanalyzer.repository.UserRepository; import com.resumeanalyzer.security.JwtService; import jakarta.servlet.*; import jakarta.servlet.http.*; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpHeaders; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component @RequiredArgsConstructor public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwtService; private final UserRepository users; @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{String header=request.getHeader(HttpHeaders.AUTHORIZATION);if(header!=null&&header.startsWith("Bearer ")&&SecurityContextHolder.getContext().getAuthentication()==null){String token=header.substring(7);if(jwtService.isValid(token)){users.findByEmailIgnoreCase(jwtService.subject(token)).ifPresent(user->{var auth=new UsernamePasswordAuthenticationToken(user,null,List.of(new SimpleGrantedAuthority(user.getRole().name())));SecurityContextHolder.getContext().setAuthentication(auth);});}}chain.doFilter(request,response);} }
